          "asserts": [
            {
              "kind": "visual",
              "expect": "跳转系统拨号界面，隐私号呼叫正常发起"
            }
          ]
        },
        {
          "sid": "A2",
          "kind": "api",
          "desc": "bindvirtualnumber 接口返回校验",
          "api_assert": {
            "path": "/hotelorder/v1/bindvirtualnumber.json",
            "expected_fields": [
              {
                "source": "meta",
                "field": "http_code",
                "expected": "200"
              },
              {
                "source": "response",
                "field": "error.code",
                "expected": "200"
